package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/signal"
	"strings"
	"syscall"

	"github.com/entireio/cli/cmd/entire/cli"
	"github.com/go-git/go-git/v6/config"
	"github.com/go-git/go-git/v6/x/plugin"
	"github.com/go-git/x/plugin/objectsigner/auto"
	"github.com/spf13/cobra"
)

func main() {
	plugin.Register(plugin.ObjectSigner(), func() plugin.Signer {
		cfgstorer, err := plugin.Get(plugin.ConfigLoader())
		if err != nil {
			return nil
		}

		global, err := cfgstorer.Load(config.GlobalScope)
		if err != nil {
			return nil
		}

		gcfg, err := global.Config()
		if err != nil {
			return nil
		}

		system, err := cfgstorer.Load(config.GlobalScope)
		if err != nil {
			return nil
		}

		gsys, err := system.Config()
		if err != nil {
			return nil
		}

		cfg := config.Merge(gcfg, gsys)

		signer, err := auto.FromConfig(auto.Config{
			SigningKey: cfg.User.SigningKey,
			Format:     auto.Format(cfg.GPG.Format),
		})
		if err != nil {
			return nil
		}

		return signer
	})

	// Create context that cancels on interrupt
	ctx, cancel := context.WithCancel(context.Background())

	// Handle interrupt signals
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigChan
		cancel()
	}()

	// Create and execute root command
	rootCmd := cli.NewRootCmd()
	err := rootCmd.ExecuteContext(ctx)
	if err != nil {
		var silent *cli.SilentError

		switch {
		case errors.As(err, &silent):
			// Command already printed the error
		case strings.Contains(err.Error(), "unknown command") || strings.Contains(err.Error(), "unknown flag"):
			showSuggestion(rootCmd, err)
		default:
			fmt.Fprintln(rootCmd.OutOrStderr(), err)
		}

		cancel()
		os.Exit(1)
	}
	cancel() // Cleanup on successful exit
}

func showSuggestion(cmd *cobra.Command, err error) {
	// Print usage first (brew style)
	fmt.Fprint(cmd.OutOrStderr(), cmd.UsageString())
	fmt.Fprintf(cmd.OutOrStderr(), "\nError: Invalid usage: %v\n", err)
}

