		return nil
	}

	signer, err := plugin.Get(plugin.ObjectSigner())
	if err != nil {
		return err
	}

	encoded := &plumbing.MemoryObject{}
	if err := commit.EncodeWithoutSignature(encoded); err != nil {
		return err
	}

	r, err := encoded.Reader()
	if err != nil {
		return err
	}

	sig, err := signer.Sign(r)
	if err != nil {
		return err
	}

	commit.Signature = string(sig)
	return nil
}

